"""Add safe diagnostics to the existing authenticated verification route only."""
from datetime import datetime, timezone
from pathlib import Path
import ast
import shutil
import sys

ROOT = Path.home() / "firely-learning"
OLD = '        if path == "/local-integration/verify" and local_mode():\n            try:\n                mode = json.loads((ROOT / "spec/v2/local-integration.json").read_text())\n                checkpoint = Path(mode["checkpoint"])\n                expected = json.loads((checkpoint / "source-resources.json").read_text())\n                first = {key: get_json(BASE + "/" + key) for key in expected}\n                second = {key: get_json(BASE + "/" + key) for key in expected}\n                if first != second or first != expected:\n                    raise RuntimeError("Authenticated resources differ from original snapshot")\n                data = summary("demo-patient-002")\n                appointment_id = "siu-appointment-17d6d563-4f77-5aac-b49b-2367195f7423"\n                assessments = [a for a in data["assessments"] if a["appointment_id"] == appointment_id]\n                if len(assessments) != 1 or assessments[0]["outcome"] != "information_complete":\n                    raise RuntimeError("New appointment assessment did not complete")\n                requirements = assessments[0]["requirements"]\n                expected_labs = {"demo-glucose-002", "lab-760b9ffe-19ca-5dbb-b2ef-8bb12d2cf2d4"}\n                if len(requirements) != 1 or set(requirements[0]["matched_record_ids"]) != expected_labs:\n                    raise RuntimeError("Qualifying glucose records differ")\n                from datetime import datetime, timezone\n                from hashlib import sha256\n                report = {"passed": True, "authenticated": True, "resource_count": len(first),\n                    "two_reads_agree": True, "original_snapshot_matches": True,\n                    "appointment_id": appointment_id, "qualifying_glucose_count": 2,\n                    "outcome": "information_complete", "documents": "deferred",\n                    "checked_at": datetime.now(timezone.utc).isoformat(),\n                    "payload_hashes": {key: sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()\n                                       for key, value in first.items()}}\n                evidence_dir = ROOT / "evidence"\n                evidence_dir.mkdir(parents=True, exist_ok=True)\n                name = "local-portal-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ") + ".json"\n                (evidence_dir / name).write_text(json.dumps(report, indent=2) + "\\n")\n                self.send_json(200, report)\n            except Exception:\n                self.send_json(502, {"passed": False, "error": "local_bridge_verification_failed"})\n            return\n\n'
NEW = '        if path == "/local-integration/verify" and local_mode():\n            stage = "load_snapshot"\n            diagnostic = {}\n            try:\n                mode = json.loads((ROOT / "spec/v2/local-integration.json").read_text())\n                checkpoint = Path(mode["checkpoint"])\n                expected = json.loads((checkpoint / "source-resources.json").read_text())\n                def read_resources(label):\n                    nonlocal stage\n                    records = {}\n                    for key in expected:\n                        stage = label + ":" + key\n                        records[key] = get_json(BASE + "/" + key)\n                    return records\n                first = read_resources("authenticated_read_1")\n                second = read_resources("authenticated_read_2")\n                diagnostic["two_reads_agree"] = first == second\n                def different_fields(left, right, prefix=""):\n                    if isinstance(left, dict) and isinstance(right, dict):\n                        paths = []\n                        for key in sorted(set(left) | set(right)):\n                            path = prefix + ("." if prefix else "") + key\n                            if key not in left or key not in right:\n                                paths.append(path)\n                            else:\n                                paths.extend(different_fields(left[key], right[key], path))\n                        return paths\n                    if isinstance(left, list) and isinstance(right, list):\n                        if len(left) != len(right):\n                            return [prefix + ".length"]\n                        return [path for index, (a, b) in enumerate(zip(left, right))\n                                for path in different_fields(a, b, prefix + "[" + str(index) + "]")]\n                    return [] if left == right else [prefix]\n                diagnostic["snapshot_differences"] = {\n                    key: different_fields(expected[key], first[key])[:50]\n                    for key in expected if expected[key] != first[key]\n                }\n                stage = "portal_summary"\n                data = summary("demo-patient-002")\n                diagnostic["returned_observation_ids"] = [r["id"] for r in data["observations"]]\n                appointment_id = "siu-appointment-17d6d563-4f77-5aac-b49b-2367195f7423"\n                assessments = [a for a in data["assessments"] if a["appointment_id"] == appointment_id]\n                diagnostic["assessment_count"] = len(assessments)\n                stage = "appointment_assessment"\n                if len(assessments) != 1:\n                    raise RuntimeError("assessment_count")\n                diagnostic["assessment_outcome"] = assessments[0]["outcome"]\n                requirements = assessments[0]["requirements"]\n                diagnostic["matched_record_ids"] = [r.get("matched_record_ids", []) for r in requirements]\n                diagnostic["requirement_outcomes"] = [r.get("outcome") for r in requirements]\n                expected_labs = {"demo-glucose-002", "lab-760b9ffe-19ca-5dbb-b2ef-8bb12d2cf2d4"}\n                if assessments[0]["outcome"] != "information_complete" or len(requirements) != 1 or set(requirements[0]["matched_record_ids"]) != expected_labs:\n                    raise RuntimeError("qualifying_results")\n                stage = "snapshot_comparison"\n                if first != second or first != expected:\n                    raise RuntimeError("snapshot_mismatch")\n                from datetime import datetime, timezone\n                from hashlib import sha256\n                report = {"passed": True, "authenticated": True, "resource_count": len(first),\n                    "two_reads_agree": True, "original_snapshot_matches": True,\n                    "appointment_id": appointment_id, "qualifying_glucose_count": 2,\n                    "outcome": "information_complete", "documents": "deferred",\n                    "checked_at": datetime.now(timezone.utc).isoformat(),\n                    "payload_hashes": {key: sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()\n                                       for key, value in first.items()}}\n                stage = "save_evidence"\n                evidence_dir = ROOT / "evidence"\n                evidence_dir.mkdir(parents=True, exist_ok=True)\n                name = "local-portal-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ") + ".json"\n                (evidence_dir / name).write_text(json.dumps(report, indent=2) + "\\n")\n                self.send_json(200, report)\n            except Exception as error:\n                report = {"passed": False, "error": "local_bridge_verification_failed",\n                          "failed_step": stage, "error_type": type(error).__name__,\n                          "diagnostic": diagnostic}\n                status = getattr(error, "code", None)\n                if isinstance(status, int) and 400 <= status <= 599:\n                    report["upstream_http_status"] = status\n                self.send_json(502, report)\n            return\n\n'

def main():
    path = ROOT / "worklist/document_viewer_server.py"
    text = path.read_text()
    if NEW in text:
        print("Diagnostics already installed. Restart the viewer and retry verification.")
        return
    if text.count(OLD) != 1:
        raise RuntimeError("Verification block differs; no file was changed")
    updated = text.replace(OLD, NEW, 1)
    ast.parse(updated)
    checkpoint = ROOT / "checkpoints" / ("portal-diagnostics-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ"))
    checkpoint.mkdir(parents=True)
    shutil.copy2(path, checkpoint / path.name)
    path.write_text(updated)
    print("PASS: safe verification diagnostics installed.")
    print("Backup:", checkpoint)
    print("Restart the viewer, sign in, and open /local-integration/verify again.")

if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print("STOP:", str(error))
        sys.exit(1)
